// pes_dispatch.hpp: runtime dispatch for translated indirect calls. The table
// maps PES code VAs to translated functions. It lives in one translation unit,
// pes_dispatch_gen.cpp (committed, generated by tools/dev/translate/gen_translated.py),
// so no pes_fn TU depends on the list of functions. A target missing from the
// table fails loudly (PES_DISPATCH_UNTRANSLATED), never silently, unless the caller
// holds a recovery: pes_dispatch_missing_handler, when set, is called first and must
// not return (the FixDemo camera rig longjmps out of the engine frame; it reports the
// missing VA and falls back). The pointer is null except around that one call.
#pragma once
#include <cstdint>

struct PesState;

struct PesDispatch {
  void (*fn)(PesState&);
};

PesDispatch pes_dispatch_lookup(uint64_t t);
[[noreturn]] void pes_dispatch_missing(uint64_t t);
extern void (*pes_dispatch_missing_handler)(uint64_t);
